import { useEffect, useRef, useState } from 'react';

export default function useInView() {
  const ref = useRef(null); const [visible, setVisible] = useState(false);
  useEffect(() => { const observer = new IntersectionObserver(([entry]) => entry.isIntersecting && setVisible(true), { threshold: 0.14 }); if (ref.current) observer.observe(ref.current); return () => observer.disconnect(); }, []);
  return [ref, visible];
}
